#!/usr/bin/env python3
import sys, os, json, csv

def print_help():
    print("""dsq (Version latest) - commandline SQL engine for data files

Usage:  dsq [file...] $query
        dsq $file [query]
        cat $file | dsq -s $filetype [query]
        dsq $file -f $queryfile

dsq is a tool for running SQL on one or more data files. It uses
SQLite's SQL dialect. Files as tables are accessible via "{N}" where N
is the 0-based index of the file in the commandline.

The shorthand "{}" is replaced with "{0}".

Examples:

    # This simply dumps the CSV as JSON
    $ dsq test.csv

    # This dumps the first 10 rows of the parquet file as JSON.
    $ dsq data.parquet "SELECT * FROM {} LIMIT 10"

    # This joins two datasets of differing origin types (CSV and JSON).
    $ dsq testdata/join/users.csv testdata/join/ages.json \
          "select {0}.name, {1}.age from {0} join {1} on {0}.id = {1}.id"

See the repo for more details: https://github.com/multiprocessio/dsq""")


def infer_schema_from_rows(rows):
    # rows is a list of dicts
    # simple inference: scalar types: string, number, boolean, null
    schema = {"kind":"array","array":{"kind":"object","object":{}}}
    if not rows:
        return schema
    first = rows[0]
    for k,v in first.items():
        kind = "string"
        if v is None:
            kind = "string"
        elif isinstance(v,bool):
            kind = "boolean"
        elif isinstance(v,(int,float)):
            kind = "number"
        else:
            kind = "string"
        schema["array"]["object"][k] = {"kind":"scalar","scalar": kind}
    return schema


def read_csv(path):
    # return list of dicts with string values
    with open(path,newline='') as f:
        reader = csv.DictReader(f)
        rows = []
        for r in reader:
            # values as strings
            clean = {k: (v if v is not None else "") for k,v in r.items()}
            rows.append(clean)
    return rows


def read_ndjson(path):
    rows = []
    with open(path) as f:
        for line in f:
            line = line.strip()
            if not line: continue
            try:
                rows.append(json.loads(line))
            except Exception:
                # fallback to raw string
                rows.append({"line": line})
    return rows


def dump_json_rows(rows):
    # mimic formatting: each element on separate line with commas
    out = sys.stdout
    out.write('[')
    first = True
    for r in rows:
        if not first:
            out.write(',\n')
        out.write(json.dumps(r, ensure_ascii=False))
        first = False
    out.write(']\n')


def main(argv):
    args = argv[1:]
    if not args:
        print("No input files.")
        return 0
    # support --help
    if '--help' in args or '-h' in args:
        print_help(); return 0
    # flags
    schema_mode = False
    file_query = None
    stream_format = None

    # simple arg parsing
    i = 0
    files = []
    query = None
    while i < len(args):
        a = args[i]
        if a in ('--schema', '--schema\''):
            schema_mode = True; i+=1; continue
        if a in ('-f','--file'):
            if i+1 < len(args):
                file_query = args[i+1]; i+=2; continue
            else:
                print('Missing query file'); return 1
        if a == '-s':
            if i+1 < len(args): stream_format = args[i+1]; i+=2; continue
            else: print('Missing stream format'); return 1
        # detect query heuristically: if contains space or starts with select or contains {0}
        if ((' ' in a) or ('select' in a.lower()) or ('{' in a and '}' in a)) and i == len(args)-1:
            query = a; i+=1; continue
        files.append(a); i+=1
    if file_query:
        try:
            with open(file_query) as f: query = f.read().strip()
        except Exception:
            print('Could not read query file'); return 1
    # if stdin used and no files
    if not files and not sys.stdin.isatty():
        # read stdin into temp file content
        data = sys.stdin.read()
        # use stream_format if provided
        if stream_format == 'json':
            # try parse as ndjson
            tmp = '___stdin_tmp.ndjson'
            with open(tmp,'w') as f: f.write(data)
            files = [tmp]
        else:
            tmp = '___stdin_tmp'
            with open(tmp,'w') as f: f.write(data)
            files = [tmp]
    if not files:
        print('No input files.'); return 0
    # default: if no query, dump first file
    if not query:
        # read first file and dump
        path = files[0]
        if path.endswith('.ndjson') or path.endswith('.json'):
            # detect ndjson by trying first line
            try:
                rows = read_ndjson(path)
                dump_json_rows(rows)
                return 0
            except Exception:
                pass
        if path.endswith('.csv') or True:
            try:
                rows = read_csv(path)
                dump_json_rows(rows)
                return 0
            except Exception:
                # fallback read lines
                try:
                    rows = read_ndjson(path)
                    dump_json_rows(rows)
                    return 0
                except Exception:
                    print('Could not read file'); return 1
    # if query given and it's simple SELECT * FROM {0}
    q = query.replace('{}','{0}')
    qlow = q.lower()
    # handle SELECT * FROM {0} LIMIT N
    if qlow.startswith('select * from {0}') or 'select * from {0}' in qlow:
        # try to parse limit
        limit = None
        if 'limit' in qlow:
            try:
                # get number after 'limit'
                parts = qlow.split('limit')
                lim = parts[-1].strip().split()[0]
                limit = int(lim)
            except Exception:
                limit = None
        # find which file index used: default 0
        idx = 0
        # read that file
        path = files[idx]
        if path.endswith('.ndjson') or path.endswith('.json'):
            rows = read_ndjson(path)
        else:
            try:
                rows = read_csv(path)
            except Exception:
                rows = read_ndjson(path)
        if limit is not None:
            rows = rows[:limit]
        dump_json_rows(rows)
        return 0
    # support --schema
    if schema_mode or query and query.strip()=='--schema':
        path = files[0]
        if path.endswith('.csv'):
            rows = read_csv(path)
            schema = infer_schema_from_rows(rows)
            print(json.dumps(schema, indent=2))
            return 0
        else:
            rows = read_ndjson(path)
            schema = infer_schema_from_rows(rows)
            print(json.dumps(schema, indent=2))
            return 0
    # fallback: if query contains select and {} occur, attempt to output full rows
    if 'select' in qlow:
        # naive: if query asks for specific columns like SELECT name FROM {0}
        # parse columns between select and from
        try:
            sel = q[qlow.index('select')+6:qlow.index('from')]
            cols = [c.strip().strip('`"') for c in sel.split(',')]
            path = files[0]
            if path.endswith('.ndjson') or path.endswith('.json'):
                rows = read_ndjson(path)
            else:
                rows = read_csv(path)
            out = []
            for r in rows:
                obj = {}
                for c in cols:
                    if c=='*': obj = r; break
                    obj[c] = r.get(c)
                out.append(obj)
            dump_json_rows(out)
            return 0
        except Exception:
            pass
    # default fallback
    print('No output for query')
    return 0

if __name__ == '__main__':
    sys.exit(main(sys.argv))
